We say that $(\nu,P)$ satisfies the completeness property if
            \begin{equation}\label{E: completeness}\tag{C}
                Q_\nu[f] = 0
                \quad
                \text{ implies }
                \quad
                f = 0 \quad \nu\text{-almost everywhere}
            \end{equation}
            for every real $f\in L^2(\nu)$.
            Equivalent forms are given in Lemma~\ref{L: Kh_dense}.

We say that $(\nu, P)$ is weakly localized if there is a countable $\pi$-system $\mathcal{A} \subset \mathcal{B}(Y)$ generating $\mathcal{B}(Y)$ such that, for every $B \in \mathcal{A}$ and every real $f \in L^2(\nu)$ we have 
            \begin{equation}\label{E: weak_localization}\tag{WL}
                0 \leq Q_{\nu}[f] \leq Q_\nu[\mathbf{1}_B]
                \quad
                \text{ implies }
                \quad
                \int_{Y \setminus B} f(y) d\nu(y) = 0.
            \end{equation}
            We say $(\nu, P)$ is strongly localized if there is such an $\mathcal{A}$ so that
            \begin{equation}\label{E: strong_localization}\tag{SL}
                0 \leq Q_\nu[f] \leq Q_\nu[\mathbf{1}_B] 
                \quad 
                \text{ implies } 
                \quad 
                f \mathbf{1}_{Y \setminus B} = 0 \quad \nu\text{-a.e.}
            \end{equation}
            for all $B \in \mathcal{A}$ and $f$ in $L^2(\nu)$.

\label{R: hierarchy}
            We have the following hierarchy of regularity assumptions on $(\nu, P)$:
            \begin{equation*}
                \eqref{E: strong_localization} \implies \eqref{E: weak_localization} \implies\eqref{E: completeness}.
            \end{equation*}
            This is proved in Lemma~\ref{L: localization_completeness}.

More explicitly, Theorem~\ref{T: general_rigidity} says that if a random probability measure $\eta$ satisfies
            \begin{equation}\label{E: three_rigidity}
                \mathbb E[\eta^{\otimes 3}] = \int_Y P_y^{\otimes 3} d\nu(y),
            \end{equation}
            then, on the probability space carrying $\eta$, there is a measurable $Y$-valued random variable $A$ with law $\nu$ such that $\eta = P_A$ almost surely.

            In general, $3$ cannot be improved to $2$ here. See Proposition~\ref{P: exponential_two_nonrigidity} for an example.

\label{R: completeness_sharpness}
            The number four in
            Theorem~\ref{T: completeness_rigidity} cannot in general
            be replaced by three. Let $E=\{0,1\}$, $Y=[0,1]$, and
            \begin{equation*}
                P_y=(1-y)\delta_0+y\delta_1.
            \end{equation*}
            Define
            \begin{equation*}
                p_\pm=\frac{1}{2}\left(1\pm\frac{1}{\sqrt{3}}\right),
                \quad
                \nu=\frac{1}{2}\delta_{p_-}
                     +\frac{1}{2}\delta_{p_+},
            \end{equation*}
            and let $\widetilde\nu$ be the uniform probability measure
            on $[0,1]$. The component measures $P_{p_-}$ and $P_{p_+}$
            are linearly independent, so $(\nu,P)$ satisfies
            \eqref{E: completeness}. However,
            \begin{equation*}
                \int_0^1 y^j\,d\nu(y)
                =\int_0^1 y^j\,d\widetilde\nu(y)
                =\frac{1}{j+1},
                \quad j=0,1,2,3.
            \end{equation*}
            Each mass assigned by $P_y^{\otimes3}$ to a point of
            $\{0,1\}^3$ is a polynomial in $y$ of degree at most three.
            Consequently,
            \begin{equation*}
                \mathcal{M}_3\left(\mathfrak{G}_\nu\right)
                =\mathcal{M}_3\left(\mathfrak{G}_{\widetilde\nu}\right),
                \quad
                \text{ yet }
                \quad
                \mathfrak{G}_\nu\ne\mathfrak{G}_{\widetilde\nu}.
            \end{equation*}
            Thus $\mathfrak{G}_\nu$ is $4$-rigid but not $3$-rigid.

\label{L: laplace_support}
            Let $0=\lambda_0<\lambda_1<\cdots$ satisfy
            \begin{equation*}
                \inf_{n\geq0}(\lambda_{n+1}-\lambda_n)>0.
            \end{equation*}
            For a finite signed Borel measure $\sigma$ on $[0,\infty)$,
            we define the Laplace transform
            \begin{equation*}
                \widehat\sigma(\lambda)
                :=\int_{[0,\infty)}e^{-\lambda y}\,d\sigma(y).
            \end{equation*}
            The following are equivalent:
            \begin{enumerate}
                \item $\displaystyle\sum_{n=1}^{\infty}
                            \frac{1}{\lambda_n}=\infty$.
                \item For every finite signed Borel measure $\sigma$
                    on $[0,\infty)$ and every $b\geq0$,
                    \begin{equation}\label{E: laplace_support}
                        \sigma|_{[0,b)}=0
                        \quad\Longleftrightarrow\quad
                        \sup_{n\geq1}e^{b\lambda_n}
                            |\widehat\sigma(\lambda_n)|<\infty.
                    \end{equation}
                \item For every nonzero finite signed Borel measure
                    $\sigma$ on $[0,\infty)$,
                    \begin{equation*}
                        \inf\operatorname{supp}|\sigma|
                        =-\limsup_{n\to\infty}
                            \frac{1}{\lambda_n}
                            \log|\widehat\sigma(\lambda_n)|,
                    \end{equation*}
                    where $\log0:=-\infty$.
            \end{enumerate}

\label{D: exponential_MS}
            We say that $\rho$ satisfies the
            M\"untz--Sz\'asz condition if there exist
            $t_0\in[0,\infty)^d$ and a sequence
            $0=\lambda_{i,0}<\lambda_{i,1}<\cdots$ for every $1\leq i\leq d$
            such that
            \begin{equation}\label{E: exponential_MS}\tag{MS}
                \begin{aligned}
                    &\inf_{n\geq0}
                        (\lambda_{i,n+1}-\lambda_{i,n})>0,
                    \quad
                    \sum_{n=1}^{\infty}\frac{1}{\lambda_{i,n}}=\infty,
                    \quad 1\leq i\leq d,
                    \quad \text{and}\\
                    &t_0+
                    \bigl\{
                        (\lambda_{1,n_1},\ldots,\lambda_{d,n_d}):
                        n_1,\ldots,n_d\geq0
                    \bigr\}
                    \subseteq\operatorname{supp}\rho.
                \end{aligned}
            \end{equation}

\label{P: exponential_two_nonrigidity}
            Suppose that $d=1$, \eqref{E: finite_partition_function}
            holds, and $T$ is not $m$-almost everywhere constant.
            If $\nu\in\mathcal{P}(Y)$ is not a point mass, then
            $\mathfrak G_\nu$ is not $2$-rigid.

\label{P: exponential_completeness}
            Suppose that $d=1$, $Y=(0,\infty)$, and
            \eqref{E: finite_partition_function} holds. Define
            \begin{equation*}
                a:=\min\operatorname{supp}\rho,
                \quad
                \text{ and }
                \quad
                \mathcal S_\rho
                :=\{t-a:t\in\operatorname{supp}\rho,\ t>a\}.
            \end{equation*}
            For $0<u\leq1$, define the weight
            \begin{equation*}
                w_\rho(u)
                :=\int_{[a,\infty)}
                    e^{-(t-a)}u^{t-a}\,d\rho(t)
                =e^a u^{-a}Z(1-\log u),
            \end{equation*}
            and set $w_\rho(0):=\rho(\{a\})$.
            Then $w_\rho$ is continuous on $[0,1]$ and positive
            on $(0,1]$. For every $\lambda\in\mathcal S_\rho$,
            the function $\frac{u^\lambda}{w_\rho(u)}$ extends
            continuously to zero with value zero.

            The following are equivalent:
            \begin{enumerate}
                \item For every $\nu\in\mathcal{P}((0,\infty))$, the pair
                    $(\nu,P)$ satisfies completeness
                    \eqref{E: completeness}.
                \item
                    \begin{equation}\label{E: weighted_muntz_completeness}
                        \overline{\operatorname{span}
                        \left\{
                            \frac{u^\lambda}{w_\rho(u)}:
                            \lambda\in\mathcal S_\rho
                        \right\}}^{\,\left\lVert\cdot\right\rVert_\infty}
                        =
                        \{g\in C[0,1]:g(0)=0\}.
                    \end{equation}
            \end{enumerate}
            Under these equivalent conditions,
            $\mathfrak{G}_\nu$ is $4$-rigid for every
            $\nu\in\mathcal{P}((0,\infty))$.

\label{L: Kh_dense}
            The following conditions are equivalent:
            \begin{enumerate}
                \item $(\nu,P)$ satisfies the completeness
                    property~\eqref{E: completeness}.
                \item The linear span of
                    \begin{equation*}
                        \{K_h:h\text{ is a bounded real-valued
                        Borel measurable map from }E\text{ to }\mathbb R\}
                    \end{equation*}
                    is dense in $L^2(\nu)$.
                \item If $(U,V)$ has joint law $\nu(du)P_u(dv)$, then
                    \begin{equation*}
                        \mathbb E[f(U)\mid V]=0
                        \quad\Longrightarrow\quad
                        f(U)=0\quad\text{almost surely},
                        \quad f\in L^2(\nu).
                    \end{equation*}
            \end{enumerate}

\label{L: moment_isometry}
            Suppose that $(\nu,P)$ satisfies~\eqref{E: completeness}, and
            let $h$ range over bounded Borel measurable maps $E\to\mathbb R$.
            \begin{enumerate}
                \item[(a)] If~\eqref{E: k_moment_identity} holds for
                $k=2$, there is a unique isometric embedding
                $W:L^2(\nu)\to L^2(\mathbb P)$ such that
                \begin{equation}\label{E: WKh}
                    WK_h=\eta(h)
                \end{equation}
                for every $h$. Moreover, $W\1=\1$, and the adjoint
                $W^*:L^2(\mathbb P)\to L^2(\nu)$ satisfies $W^*W=I$ and is
                characterized by
                \begin{equation}\label{E: adjoint_characterization}
                    \left\langle W^*u,K_h\right\rangle_{L^2(\nu)}=\mathbb E[u\,\eta(h)],
                    \quad u\in L^2(\mathbb P),
                \end{equation}
                for every $h$.
                \item[(b)] If~\eqref{E: k_moment_identity} holds for
                $k=3$, then
                \begin{equation}\label{E: compressed_multiplication}
                    W^*M^\mathbb P_{\eta(h)}W=M^\nu_{K_h}.
                \end{equation}
                \item[(c)] If~\eqref{E: k_moment_identity} holds for
                $k=4$, then
                \begin{equation}\label{E: exact_intertwining}
                    M^\mathbb P_{\eta(h)}W=WM^\nu_{K_h}.
                \end{equation}
            \end{enumerate}

\label{L: localization_completeness}
            Strong localization implies weak localization, and weak
            localization implies completeness:
            \begin{equation*}
                \eqref{E: strong_localization}
                \quad\Longrightarrow\quad
                \eqref{E: weak_localization}
                \quad\Longrightarrow\quad
                \eqref{E: completeness}.
            \end{equation*}

\label{L: laplace_uniqueness}
            For $1\leq i\leq d$, let
            $0=\lambda_{i,0}<\lambda_{i,1}<\cdots\to\infty$ satisfy
            $\sum_{n\geq1}\lambda_{i,n}^{-1}=\infty$.
            Let $\sigma$ be a finite signed Borel measure on
            $[0,\infty)^d$. If
            \begin{equation*}
                \int_{[0,\infty)^d}
                    \exp\left(-\sum_{i=1}^d\lambda_{i,n_i}y_i\right)
                    \,d\sigma(y)=0
            \end{equation*}
            for all nonnegative integers $n_1,\ldots,n_d$, then
            $\sigma=0$.

\label{L: multivariate_laplace_support}
            Let $\sigma$ be a finite signed Borel measure on $[0,\infty)^d$
            and let $b\in[0,\infty)^d$. For each $1\leq i\leq d$, let
            $0=\mu_{i,0}<\mu_{i,1}<\cdots$ be uniformly separated and satisfy
            \begin{equation*}
                \sum_{n=1}^{\infty}\frac{1}{\mu_{i,n}}=\infty.
            \end{equation*}
            Write $\mu_{\boldsymbol n}:=(\mu_{1,n_1},\ldots,\mu_{d,n_d})$.
            Suppose that, for some $0\leq C<\infty$,
            \begin{equation*}
                \left|\int_{[0,\infty)^d}
                    e^{-\left\langle y,\mu_{\boldsymbol n}\right\rangle}\,d\sigma(y)\right|
                \leq C e^{-\left\langle b,\mu_{\boldsymbol n}\right\rangle}
                \quad
                \text{ for all }
                \quad
                \boldsymbol n\in\mathbb N_0^d.
            \end{equation*}
            Then
            \begin{equation*}
                \sigma\big|_{[0,\infty)^d
                    \setminus\prod_{i=1}^d[b_i,\infty)}=0.
            \end{equation*}

When $d=1$, the conclusion follows from
            Proposition~\ref{L: laplace_support}. Suppose that $d\geq2$.
            Fix a coordinate $i$. We show that $\sigma$ vanishes on
            \begin{equation*}
                H_i:=\{y\in[0,\infty)^d:y_i<b_i\}
            \end{equation*}
            by applying the scalar support lemma to weighted projections
            onto that coordinate, and then using uniqueness in the remaining
            coordinates.

            Fix indices $n_j\geq0$ for $j\ne i$, and write
            $\boldsymbol n_{-i}:=(n_j)_{j\ne i}$.
            For each Borel set $A\subseteq[0,\infty)$, define
            \begin{equation*}
                \sigma_{i,\boldsymbol n_{-i}}(A)
                :=\int_{[0,\infty)^d}\1_A(y_i)
                    \exp\left(-\sum_{j\ne i}\mu_{j,n_j}y_j\right)
                    \,d\sigma(y).
            \end{equation*}
            This is a finite signed measure because the exponential weight
            lies in $[0,1]$. Its Laplace transform at $\mu_{i,n}$ is the
            integral in the hypothesis with $n_i=n$. Hence
            \begin{equation*}
                \left|\widehat\sigma_{i,\boldsymbol n_{-i}}(\mu_{i,n})\right|
                \leq C\exp\left(-b_i\mu_{i,n}
                              -\sum_{j\ne i}b_j\mu_{j,n_j}\right)
                \leq C e^{-b_i\mu_{i,n}}
                \quad
                \text{ for all }
                \quad n\geq0,
            \end{equation*}
            where the second inequality uses $b_j\geq0$ and
            $\mu_{j,n_j}\geq0$. Proposition~\ref{L: laplace_support} gives
            \begin{equation}\label{E: weighted_projection_support}
                \sigma_{i,\boldsymbol n_{-i}}|_{[0,b_i)}=0
            \end{equation}
            for every choice of the remaining indices.

            To recover $\sigma$ on $H_i$, fix a Borel set
            $A\subseteq[0,b_i)$ and write $y_{-i}:=(y_j)_{j\ne i}$.
            Define a finite signed measure $\tau_A$ on $[0,\infty)^{d-1}$ by
            \begin{equation*}
                \tau_A(D):=\int_{[0,\infty)^d}
                    \1_A(y_i)\1_D(y_{-i})\,d\sigma(y)
                \quad
                \text{ for all }
                \quad D\in\mathcal{B}([0,\infty)^{d-1}).
            \end{equation*}
            For every choice of $n_j\geq0$, $j\ne i$, the definitions give
            \begin{align*}
                \int_{[0,\infty)^{d-1}}
                    \exp\left(-\sum_{j\ne i}\mu_{j,n_j}u_j\right)\,d\tau_A(u)
                &=\int_{[0,\infty)^d}\1_A(y_i)
                    \exp\left(-\sum_{j\ne i}\mu_{j,n_j}y_j\right)\,d\sigma(y)\\
                &=\sigma_{i,\boldsymbol n_{-i}}(A)=0,
            \end{align*}
            where $u=(u_j)_{j\ne i}$ and the last equality follows from
            Equation~\eqref{E: weighted_projection_support}.
            Lemma~\ref{L: laplace_uniqueness}, applied to the remaining
            sequences, therefore gives $\tau_A=0$.

            Thus $\sigma$ assigns zero mass to every rectangle specified by
            $y_i\in A$ and $y_{-i}\in D$, with $A\subseteq[0,b_i)$ and $D$
            Borel. These rectangles form a $\pi$-system generating
            $\mathcal{B}(H_i)$ and include $H_i$ itself. Since $\sigma$ is finite,
            the $\pi$--$\lambda$ theorem gives $\sigma|_{H_i}=0$.
            Applying this to every coordinate yields
            \begin{equation*}
                |\sigma|\left([0,\infty)^d
                    \setminus\prod_{i=1}^d[b_i,\infty)\right)
                \leq\sum_{i=1}^d|\sigma|(H_i)=0,
            \end{equation*}
            which proves the claim.

\label{L: normalizer_bound}
            For every $c\in U$, the map
            \begin{equation*}
                y\longmapsto z(y)e^{-\langle y,c\rangle}
            \end{equation*}
            is bounded on $Y$.

Fix $c\in U$ and choose $r$ with $t_0<r<c$.
            Choose
            \begin{equation*}
                0<\varepsilon<\min_{1\leq i\leq d}
                    \{r_i-(t_0)_i\},
                \quad
                V:=B(t_0,\varepsilon)\cap[0,\infty)^d,
            \end{equation*}
            where $B(t_0,\varepsilon)$ is the open Euclidean ball.
            Then $t\leq r$ for every $t\in V$, and
            $t_0\in\operatorname{supp}\rho$ gives $\rho(V)>0$.
            Choose $y_*\in Y$. Equation~\eqref{E: finite_partition_function}
            gives
            \begin{equation*}
                0<\rho(V)\leq e^{\langle y_*,r\rangle}Z(y_*)<\infty.
            \end{equation*}
            For every $y\in Y$,
            \begin{equation*}
                Z(y)\geq\int_V e^{-\langle y,t\rangle}\,d\rho(t)
                    \geq e^{-\langle y,r\rangle}\rho(V).
            \end{equation*}
            Consequently,
            \begin{equation*}
                z(y)e^{-\langle y,c\rangle}
                \leq\frac{e^{-\langle y,c-r\rangle}}{\rho(V)}
                \leq\frac{1}{\rho(V)},
            \end{equation*}
            which proves the claim.

\label{C: exponential_completeness_atom}
            Under the assumptions of
            Proposition~\ref{P: exponential_completeness}, suppose
            additionally that $\rho(\{a\})>0$. Then completeness
            \eqref{E: completeness} holds for every
            $\nu\in\mathcal{P}((0,\infty))$ if and only if
            \begin{equation*}
                \sup_{\substack{F\subseteq\mathcal S_\rho\\
                                F\text{ finite}}}
                    \sum_{\lambda\in F}
                        \frac{\lambda}{1+\lambda^2}
                =\infty.
            \end{equation*}

\label{Ex: exponential_completeness_weight}
            Let $E=[0,1]$, $T(x)=x$, and $Y=(0,\infty)$.
            Consider the two base measures
            \begin{equation*}
                \rho_-:=\sum_{n\geq1}e^{-2\pi n}\delta_{1/n},
                \quad
                \rho_+:=\delta_0+\rho_-.
            \end{equation*}
            Both have support
            \begin{equation*}
                \operatorname{supp}\rho_-=\operatorname{supp}\rho_+
                    =\{0\}\cup\{1/n:n\geq1\},
            \end{equation*}
            and both define exponential kernels with finite,
            positive partition functions on $(0,\infty)$.
            Denote these kernels and partition functions by
            $P_y^\pm$ and $Z_\pm(y)$.

            Since $\rho_+(\{0\})=1$ and
            \begin{equation*}
                \sum_{n\geq1}
                    \frac{1/n}{1+1/n^2}
                =\infty,
            \end{equation*}
            Corollary~\ref{C: exponential_completeness_atom}
            shows that $(\nu,P^+)$ is complete for every
            $\nu\in\mathcal{P}((0,\infty))$.

            For $P^-$, define
            \begin{equation*}
                h(y):=\sum_{k\geq0}
                    \frac{(-1)^k\pi^{2k+1}y^{2k}}
                         {(2k+1)!(2k)!}.
            \end{equation*}
            The ratio test gives locally uniform convergence. The
            coefficients are chosen so that termwise Laplace
            integration produces $\sin(\frac{\pi}{t})$, which vanishes
            at every $t=\frac1n$. For every
            $t>0$, integration of its absolute terms gives
            \begin{equation*}
                \int_0^\infty e^{-ty}|h(y)|\,dy
                \leq
                \sum_{k\geq0}
                    \frac{\pi^{2k+1}}
                         {(2k+1)!t^{2k+1}}
                =\sinh\left(\frac{\pi}{t}\right).
            \end{equation*}
            Termwise integration is therefore justified and yields
            \begin{equation*}
                \int_0^\infty e^{-ty}h(y)\,dy
                =\sin\left(\frac{\pi}{t}\right).
            \end{equation*}
            In particular,
            \begin{equation*}
                0<A:=\int_0^\infty Z_-(y)|h(y)|\,dy
                \leq
                \sum_{n\geq1}e^{-2\pi n}\sinh(\pi n)
                <\infty.
            \end{equation*}
            Positivity of $A$ follows from $h(0)=\pi$ and continuity.
            Define
            \begin{equation*}
                d\nu(y):=\frac{Z_-(y)|h(y)|}{A}\,dy,
                \quad
                f(y):=\operatorname{sgn}h(y).
            \end{equation*}
            Then $\nu$ is a probability measure and
            $\left\lVertf\right\rVert_{L^2(\nu)}=1$. Nevertheless, the signed
            mixture associated with $P^-$ satisfies
            \begin{equation*}
                Q_\nu^-[f](\{1/n\})
                =
                \frac{e^{-2\pi n}}{A}
                    \int_0^\infty e^{-y/n}h(y)\,dy
                =
                \frac{e^{-2\pi n}}{A}\sin(\pi n)
                =0
            \end{equation*}
            for every $n\geq1$. Since $P_y^-$ is concentrated
            on $\{1/n:n\geq1\}$, this proves $Q_\nu^-[f]=0$.
            Thus $(\nu,P^-)$ is not complete, despite having
            the same statistic support as the universally
            complete kernel $P^+$.

\label{L: product_law_rigidity}
            For every $\mu\in\mathcal{P}(E)$, the directing law $\delta_\mu$
            is $2$-rigid.

\label{L: four_chord}
            Let $P,Q\in\mathcal{P}(E)$ and suppose that $Q\leq MP$ for some
            $M>1$. Choose $0<\delta<\frac{1}{M-1}$, and define
            \begin{equation*}
                (\vartheta_0,\vartheta_1,\vartheta_2,\vartheta_3)
                    =\left(-\delta,0,\frac{1}{2},1\right),
                \quad\text{ and }\quad
                a_i=-\frac{1}
                    {\prod_{k\ne i}(\vartheta_i-\vartheta_k)}.
            \end{equation*}
            Write $\mu_\vartheta:=P+\vartheta(Q-P)$.
            Then all four measures $\mu_{\vartheta_i}$ belong to $\mathcal{P}(E)$.
            The finite signed measure
            \begin{equation*}
                \Xi_{P,Q}:=\sum_{i=0}^3a_i\delta_{\mu_{\vartheta_i}}
            \end{equation*}
            on $\mathcal{P}(E)$ satisfies
            \begin{equation}\label{E: four_chord_cancellation}
                \begin{aligned}
                    \mathcal{M}_j(\Xi_{P,Q})&=0
                        \quad\text{ for all }\quad j\in\{0,1,2\},\\
                    \mathcal{M}_3(\Xi_{P,Q})&=-(Q-P)^{\otimes3}.
                \end{aligned}
            \end{equation}
            Moreover, $a_0,a_2>0$ and $a_1,a_3<0$, and the Jordan
            negative part $\Xi_{P,Q}^-$ satisfies
            \begin{equation*}
                \Xi_{P,Q}^-\leq -a_1\delta_P-a_3\delta_Q.
            \end{equation*}

\label{L: exponential_convex_representation}
            Let $F:[0,\infty)\to\mathbb R$ be continuous. Suppose that
            \begin{equation*}
                \left[F\left(s_j+s_k\right)\right]_{j,k=1}^n
            \end{equation*}
            is positive semidefinite for every $n\geq1$ and every
            $s_1,\ldots,s_n\geq0$. Then there is a unique finite positive
            measure $\mu$ on $\mathbb R$ such that
            \begin{equation}\label{E: exponential_convex_representation}
                F\left(t\right)=\int_\mathbb R e^{-\beta t}\,d\mu\left(\beta\right),
                \quad t\geq0.
            \end{equation}
            If $F$ is bounded, then $\mu$ is supported in $[0,\infty)$
            and $F$ is completely monotone on $(0,\infty)$:
            \begin{equation*}
                (-1)^nF^{(n)}(t)\geq0,
                \quad n\geq0,\quad t>0.
            \end{equation*}
            If, in addition, $F(0)=1$, then $\mu$ is a probability measure.

\label{L: spherical_pair}
            If $(X_1,X_2)$ is spherically symmetric, then $\eta$ is
            symmetric almost surely and there is a unique probability
            measure $\Pi$ on $[0,\infty)$ such that
            \begin{equation}\label{E: spherical_pair_mixture}
                \mathcal{L}\left(X_1,X_2\right)
                =\int_{[0,\infty)}\gamma_v^{\otimes2}\,d\Pi(v).
            \end{equation}
            Thus the pair has a unique rotatable extension. The given
            exchangeable extension need not coincide with this extension.

\label{C: schoenberg_two}
            A spherically symmetric probability measure on $\mathbb R^2$ is
            the law of $\left(X_1,X_2\right)$ for some infinite exchangeable
            sequence $X$ if and only if its characteristic function is
            \begin{equation*}
                u\longmapsto\int_{[0,\infty)}e^{-\frac{v}{2}\left\lVertu\right\rVert^2}\,d\Pi(v)
            \end{equation*}
            for some probability measure $\Pi$ on $[0,\infty)$.
            In this case $\Pi$ is unique.

\label{C: gaussian_three_rigidity}
            Let $\Pi\in\mathcal{P}([0,\infty))$, and let $\eta$ be a random
            probability measure on $\mathbb R$. If
            \begin{equation}\label{E: gaussian_third_moment_rigidity}
                \mathbb E\left[\eta^{\otimes3}\right]
                =\int_{[0,\infty)}\gamma_v^{\otimes3}\,d\Pi(v),
            \end{equation}
            then there is a random variable $V\sim\Pi$, on the probability
            space carrying $\eta$, such that $\eta=\gamma_V$ almost surely.

Let $\eta$ be the directing measure of $X$. Spherical symmetry
            of the triple and Equation~\eqref{E: definetti_characteristic}
            give a continuous function $F:[0,\infty)\to\mathbb R$ such that
            \begin{equation}\label{E: spherical_triple_generator}
                \mathbb E\left[\prod_{j=1}^3\varphi_\eta(t_j)\right]
                =F(t_1^2+t_2^2+t_3^2).
            \end{equation}
            Taking $t_3=0$ and applying Lemma~\ref{L: spherical_pair}
            gives a unique probability measure $\Pi$ on $[0,\infty)$
            satisfying
            \begin{equation*}
                F(u)=\int_{[0,\infty)}e^{-vu/2}\,d\Pi(v),
                \quad u\geq0.
            \end{equation*}
            Substituting this representation into
            Equation~\eqref{E: spherical_triple_generator} shows that
            \begin{equation*}
                \mathcal{L}\left(X_1,X_2,X_3\right)
                =\int_{[0,\infty)}\gamma_v^{\otimes3}\,d\Pi(v).
            \end{equation*}
            Corollary~\ref{C: gaussian_three_rigidity} now gives a random
            variable $V\sim\Pi$ such that $\eta=\gamma_V$ almost surely.
            Conditional iid sampling gives
            \begin{equation*}
                X\stackrel d=\left(\sqrt V G_i\right)_{i=1}^\infty,
            \end{equation*}
            where $G_1,G_2,\ldots$ are iid standard Gaussian random
            variables independent of $V$. Thus $X$ is rotatable.

\label{L: bottom_energy_localization}
            Let $d\geq2$, suppose that $Z(1)<\infty$ and
            $\operatorname{supp}(T_*m)=[0,\infty)$, and let
            $F:[0,\infty)\to[0,\infty)$ be continuous. If a random
            probability measure $\eta$ on $E$ satisfies
            \begin{equation*}
                \mathbb E\left[\eta^{\otimes d}\right](dx)
                =F\left(\sum_{j=1}^dT(x_j)\right)\,dm^{\otimes d}(x),
            \end{equation*}
            then, for every bounded real-valued Borel function $f$ that
            vanishes outside $\{T\leq M\}$ for some $0\leq M<\infty$,
            \begin{equation*}
                \int_{E^2}f(x)f(y)F\left(T(x)+T(y)\right)\,dm(x)dm(y)\geq0.
            \end{equation*}

Every energy sublevel set has finite $m$-measure. Indeed, on
            $\{T\leq M\}$ we have $e^{-T}\geq e^{-M}$, and hence
            \begin{equation*}
                m(T\leq M)\leq e^MZ(1)<\infty.
            \end{equation*}
            The integral in the conclusion is therefore absolutely
            convergent: $F$ is bounded on $[0,2M]$, while $f$ is bounded
            and vanishes outside $\{T\leq M\}$. Write $J$ for this
            integral.

            If $d=2$, the moment identity gives $J=\mathbb E[\eta(f)^2]\geq0$
            directly. Suppose that $d\geq3$. Full support of $\rho=T_*m$
            and the sublevel estimate give
            $0<m(T\leq n^{-1})<\infty$ for $n\geq1$, so
            \begin{equation*}
                u_n(x):=\frac{\1_{\{T\leq n^{-1}\}}(x)}
                                 {m(T\leq n^{-1})}
            \end{equation*}
            is a bounded nonnegative function, and $u_n\,dm$ is a
            probability measure concentrated on $\{T\leq n^{-1}\}$. The
            moment identity gives
            \begin{equation*}
                0\leq\mathbb E\left[\eta(f)^2\eta(u_n)^{d-2}\right]
                =\int_{E^d}f(x_1)f(x_2)\prod_{j=3}^du_n(x_j)
                    F\left(\sum_{j=1}^dT(x_j)\right)\,dm^{\otimes d}(x)
                =:J_n.
            \end{equation*}
            On the support of the integrand defining $J_n$,
            \begin{equation*}
                0\leq\sum_{j=3}^dT(x_j)\leq\frac{d-2}{n}.
            \end{equation*}
            Since $u_n\,dm$ is a probability measure,
            \begin{equation*}
                \left|J_n-J\right|
                \leq\left\lVertf\right\rVert_\infty^2m(T\leq M)^2
                    \sup_{\substack{0\leq r\leq2M\\
                                    0\leq h\leq(d-2)/n}}
                    \left|F(r+h)-F(r)\right|.
            \end{equation*}
            Uniform continuity of $F$ on $[0,2M+d-2]$ makes the right-hand
            side tend to zero. Thus $J_n\to J$, and $J\geq0$.

Fix $s_1,\ldots,s_k\geq0$ and $c_1,\ldots,c_k\in\mathbb R$. For
            $\varepsilon>0$, the sets
            \begin{equation*}
                I_{j,\varepsilon}
                :=(s_j-\varepsilon,s_j+\varepsilon)\cap[0,\infty)
            \end{equation*}
            are bounded, nonempty and relatively open, so full support and
            local finiteness give $0<\rho(I_{j,\varepsilon})<\infty$. The
            function
            \begin{equation*}
                f_\varepsilon(x)
                :=\sum_{j=1}^k
                    \frac{c_j\1_{\{T\in I_{j,\varepsilon}\}}(x)}
                         {\rho(I_{j,\varepsilon})}
            \end{equation*}
            is bounded, Borel, and vanishes outside an energy sublevel set.
            The assumed inequality and $\rho=T_*m$ give
            \begin{equation*}
                0\leq\sum_{j,\ell=1}^k c_jc_\ell
                    \frac{\displaystyle
                        \int_{I_{j,\varepsilon}}\int_{I_{\ell,\varepsilon}}
                        F(r+t)\,d\rho(r)d\rho(t)}
                         {\rho(I_{j,\varepsilon})\rho(I_{\ell,\varepsilon})}.
            \end{equation*}
            Each fraction is an average of $F(r+t)$ over points with
            $\left|r+t-s_j-s_\ell\right|<2\varepsilon$, so by continuity it tends
            to $F(s_j+s_\ell)$ as $\varepsilon\downarrow0$. Passing to the
            limit in the finite sum gives
            $\sum_{j,\ell}c_jc_\ell F(s_j+s_\ell)\geq0$.

\label{L: canonical_laplace_support}
            Suppose that Equation~\eqref{E: critical_parameter_intro}
            holds. Let $d\geq1$, and let $\mu$ be a finite positive Borel
            measure on $\mathbb R$ such that
            \begin{equation*}
                F(t)=\int_\mathbb R e^{-\beta t}\,d\mu(\beta),
                \quad t\geq0.
            \end{equation*}
            If $F(\sum_{j=1}^dT(x_j))$ is the $m^{\otimes d}$-density of
            a probability measure $Q_d$, then $\mu((-\infty,0])=0$,
            Equation~\eqref{E: radial_mixing_law} defines a probability
            measure $\nu_d$, and
            $Q_d=\int_{(0,\infty)}P_\beta^{\otimes d}\,d\nu_d(\beta)$.

All integrands below are nonnegative, so Tonelli's theorem
            applies without any prior integrability assumption. Since
            $Q_d$ has total mass one,
            \begin{equation*}
                1
                =\int_{E^d}F\left(\sum_{j=1}^dT(x_j)\right)\,dm^{\otimes d}(x)
                =\int_\mathbb R\int_{E^d}
                    e^{-\beta\sum_{j=1}^dT(x_j)}
                    \,dm^{\otimes d}(x)\,d\mu(\beta)
                =\int_\mathbb R Z(\beta)^d\,d\mu(\beta).
            \end{equation*}
            By hypothesis, $Z(\beta)=\infty$ for every $\beta\leq0$.
            Hence $\mu((-\infty,0])=0$, and $\nu_d$ is a probability
            measure on $(0,\infty)$. The mixture
            $\int P_\beta^{\otimes d}\,d\nu_d(\beta)$ has
            $m^{\otimes d}$-density
            \begin{equation*}
                \int_{(0,\infty)}
                    \frac{e^{-\beta\sum_{j=1}^dT(x_j)}}{Z(\beta)^d}
                    \,d\nu_d(\beta)
                =F\left(\sum_{j=1}^dT(x_j)\right),
            \end{equation*}
            which proves the asserted identity.

Take $E=\mathbb R$, $m(dx)=dx$, and $T(x)=\left|x\right|^q$. Then $T_*m$ has
            a strictly positive density on $(0,\infty)$, so its support is
            $[0,\infty)$, and
            \begin{equation}\label{E: lq_partition_function}
                Z_q(\beta)=\int_\mathbb R e^{-\beta\left|x\right|^q}\,dx
                =2\Gamma\left(1+\frac1q\right)\beta^{-1/q},
                \quad \beta>0.
            \end{equation}
            The integral is infinite for $\beta\leq0$, so
            Equation~\eqref{E: critical_parameter_intro} holds. Since
            $\left\lVertx\right\rVert_q=(\sum_jT(x_j))^{1/q}$, the energy profile of
            Equation~\eqref{E: lq_density_intro} is
            \begin{equation*}
                F(s)=c_{q,d,\lambda}e^{-\lambda s^\alpha},
                \quad \alpha:=\frac1q.
            \end{equation*}
            Theorem~\ref{T: energy_radial_extendibility} reduces each
            assertion to a property of $F$.

            (a) If $0<q<1$, then $\alpha>1$, and
            \begin{equation*}
                \frac{d^2}{ds^2}e^{-\lambda s^\alpha}
                =e^{-\lambda s^\alpha}\lambda\alpha s^{\alpha-2}
                    \left[\lambda\alpha s^\alpha-(\alpha-1)\right]
            \end{equation*}
            is negative for all sufficiently small $s>0$. Hence $F$ is not
            completely monotone, and no infinite exchangeable extension
            exists.

            (b) If $q=1$, then $F$ is a single exponential, and the density
            factorizes into iid Laplace densities with rate $\lambda$.
            The theorem gives uniqueness for every $d\geq2$.

            (c) If $q>1$, then $0<\alpha<1$, and there is a nondegenerate
            positive $\alpha$-stable random variable $B_{\alpha,\lambda}$
            with
            \begin{equation}\label{E: lq_stable_laplace}
                \mathbb E\left[e^{-sB_{\alpha,\lambda}}\right]
                =e^{-\lambda s^\alpha},\quad s\geq0;
            \end{equation}
            see \cite[Chapter~XIII, Section~6]{Feller}. Thus $F$ is
            completely monotone, with representing measure $\mu$ equal to
            $c_{q,d,\lambda}$ times the law $\xi_{\alpha,\lambda}$ of
            $B_{\alpha,\lambda}$. The integral representation of a negative
            power and Tonelli's theorem give
            \begin{equation*}
                \int_{(0,\infty)}u^{-d/q}\,d\xi_{\alpha,\lambda}(u)
                =\frac{1}{\Gamma(d/q)}\int_0^\infty
                    t^{d/q-1}e^{-\lambda t^{1/q}}\,dt
                =\frac{q\,\Gamma(d)}{\Gamma(d/q)\lambda^d}<\infty.
            \end{equation*}
            Equations~\eqref{E: radial_mixing_law}
            and~\eqref{E: lq_partition_function} therefore identify the
            mixing law as the polynomial tilt
            \begin{equation}\label{E: lq_mixing_law}
                d\nu_d(\beta)
                =\frac{\beta^{-d/q}}
                    {\displaystyle\int_{(0,\infty)}
                        u^{-d/q}\,d\xi_{\alpha,\lambda}(u)}
                    \,d\xi_{\alpha,\lambda}(\beta).
            \end{equation}
            This law is not a point mass, since the stable law is
            nondegenerate and the tilting weight is strictly positive.
            The theorem gives an extension that is unique for $d\geq3$
            and not unique for $d=2$.

\label{P: finite_independent_bounds}
            Suppose that $P_1,\ldots,P_m$ are linearly independent.
            \begin{enumerate}
                \item[(a)] If $\Lambda$ has at most $m$ atoms and
                $\mathcal{M}_3(\Lambda)=\mathcal{M}_3(\Lambda_0)$, then
                $\Lambda=\Lambda_0$.
                \item[(b)] The law $\Lambda_0$ is $4$-rigid.
            \end{enumerate}

\label{C: finite_joint_irreducibility}
            If $P_1,\ldots,P_m$ are jointly irreducible, then
            $\Lambda_0$ is $2$-rigid.

\label{P: finite_block_bounds}
            Suppose that $P_1^{\otimes r},\ldots,P_m^{\otimes r}$ are
            linearly independent for some integer $r\geq1$.
            \begin{enumerate}
                \item[(a)] If $\Lambda$ has at most $m$ atoms and
                $\mathcal{M}_{2r+1}(\Lambda)=\mathcal{M}_{2r+1}(\Lambda_0)$, then
                $\Lambda=\Lambda_0$.
                \item[(b)] The law $\Lambda_0$ is $(2r+2)$-rigid.
            \end{enumerate}
